    collection_name = f"mem0_demo_{run_id}"

    logger.info("Starting Mem0 Chroma lifecycle demo")
    logger.info("run_id=%s collection_name=%s", run_id, collection_name)
    logger.info("Chroma persistence path=%s", CHROMA_DIR)

